def transform(grid):
    h, w = len(grid), len(grid[0])

    # The divider is a uniform row or column whose color occurs nowhere else.
    divider = None
    for r in range(h):
        color = grid[r][0]
        if all(x == color for x in grid[r]) and all(
            grid[i][j] != color for i in range(h) if i != r for j in range(w)
        ):
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            color = grid[0][c]
            if all(grid[r][c] == color for r in range(h)) and all(
                grid[i][j] != color for j in range(w) if j != c for i in range(h)
            ):
                divider = ("col", c)
                break

    if divider[0] == "row":
        _, r = divider
        a, b = grid[:r], grid[r + 1:]
    else:
        _, c = divider
        a = [row[:c] for row in grid]
        b = [row[c + 1:] for row in grid]

    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    color = next(iter(shared))
    return [
        [3 if a[i][j] == color and b[i][j] == color else color
         for j in range(len(a[0]))]
        for i in range(len(a))
    ]
